def check_intersections(n, points):
    def slope(p1, p2):
        return (p2[1] - p1[1]) / (p2[0] - p1[0])

    stack = []
    for i in range(1, n):
        while len(stack) >= 2 and slope(points[i], points[stack[-2]]) * slope(points[i], points[stack[-1]]) < 0:
            stack.pop()
        stack.append(i)

    return len(stack) != n

